/* Version 2: CodeMie UI, with the richer personal workspace flows reviewed in Echo future. */
'use strict';
const baseAction=handleAction, baseAfterRender=afterRender, baseKnowledgeReader=pages.knowledge;
const baseAISettings=pages['settings-ai'], baseRecipes=pages.recipes, baseMeeting=pages.meeting;
Object.assign(PAGE_INFO,{
 capture:['Capture','Record, import and review meeting context.','mic'],
 'knowledge-pages':['Pages','Read and edit your own files.','file'],
 'knowledge-setup':['Schema & skills','Your vault, rules and access.','settings'],
 'settings-notifications':['Notifications & focus','Control what interrupts you.','bell'],
 proposal:['Workspace proposal','Design and functionality review.','grid']
});
const workspaceWidgets=[
 {id:'brief',name:'Morning brief',from:'Scheduler · sourced daily summary',ico:'spark',width:'wide'},
 {id:'decisions',name:'Waiting for you',from:'Core · approvals and open decisions',ico:'inbox',width:'standard'},
 {id:'agenda',name:'Your day',from:'Calendar · Microsoft 365 and local events',ico:'calendar',width:'wide'},
 {id:'work',name:'My commitments',from:'Core · promises across meetings and messages',ico:'check',width:'standard'},
 {id:'knowledge',name:'Knowledge',from:'Core · vault changes and health',ico:'book',width:'standard'},
 {id:'usage',name:'AI usage',from:'Core · profile usage and caps',ico:'chart',width:'standard'},
 {id:'focus',name:'Interruptions & focus',from:'Core · quiet hours and critical rules',ico:'bell',width:'standard'},
 {id:'github',name:'GitHub reviews',from:'Plugin · GitHub',ico:'github',width:'standard',plugin:'github'},
 {id:'routines',name:'Upcoming routines',from:'Plugin · Scheduler',ico:'automation',width:'standard',plugin:'scheduler'},
 {id:'focus-card',name:'Focus card',from:'Plugin · your own unchanged Echo package',ico:'puzzle',width:'standard',plugin:'focus-card'}
];
function ensureV2(){
 if(!state.workspaceWidgets)state.workspaceWidgets=workspaceWidgets.slice(0,7).map(w=>({id:w.id,width:w.width}));
 state.reviewedDecisions ||= [];state.commitments ||= {};state.healthResolved ||= [];state.approvedChanges ||= [];
 state.vaultTab ||= 'Vault';state.recipeTab ||= 'Rules';state.captureSource ||= 'Microsoft Teams';state.triageLane ||= 'critical';
 state.jobRouting ||= {};state.accent='codemie';save();
}
applyTheme=function(){const t=state.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):state.theme;document.documentElement.dataset.theme=t;document.documentElement.dataset.density=state.density;document.documentElement.dataset.sidebar=state.sidebar;['--accent','--accent-soft','--accent-line'].forEach(p=>document.documentElement.style.removeProperty(p))};
head=function(title=PAGE_INFO[page][0],sub=PAGE_INFO[page][1],actions=''){return `<header class="page-head"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="page-actions">${actions}</div></header>`};
activeNav=function(name){if(page.startsWith('knowledge'))return name==='knowledge';if(['meeting','recipes','capture'].includes(page))return name==='meetings';if(['space','people'].includes(page))return name==='spaces';if(page==='files')return name==='inbox';if(page.startsWith('plugin'))return name==='plugins';if(page.startsWith('settings'))return name==='settings';return page===name};
shell=function(){
 ensureV2();document.title=`${PAGE_INFO[page][0]} · CodeMie Connect`;
 const nav=(items)=>items.map(([id,label,ico,count])=>`<a href="${route(id)}" class="nav-item ${activeNav(id)?'active':''}" ${activeNav(id)?'aria-current="page"':''} title="${label}">${icon(ico)}<span>${label}</span>${count?`<span class="count">${count}</span>`:''}</a>`).join('');
 document.body.innerHTML=`<a class="screen-reader" href="#main">Skip to content</a><div class="app"><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="index.html"><img src="assets/codemie-logo.svg" alt=""><div><div class="brand-sub">EPAM AI/RUN</div><div class="brand-name">CodeMie<small>CONNECT</small></div></div></a><button class="workspace-btn" data-action="switch-space"><div class="grow"><strong class="small">${esc(state.workspaceName||'Personal workspace')}</strong><span class="dim" style="display:block;font-size:9px">On this device</span></div>${icon('down')}</button><div class="nav-label">WORKSPACE</div><nav class="nav-group">${nav([['today','Today','sun'],['inbox','Inbox','inbox',state.criticalAck?'0':'1'],['chat','Chat','chat'],['calendar','Calendar','calendar'],['meetings','Meetings','video'],['knowledge','Knowledge','book'],['spaces','Spaces','spaces']])}</nav><div class="nav-label">CAPABILITIES</div><nav class="nav-group">${nav([['automations','Automations','automation'],['plugins','Plugins','puzzle'],['analytics','Usage','chart']])}</nav><div class="side-bottom">${nav([['settings','Settings','settings'],['library','Screen library','grid']])}<a class="ai-status" href="settings-ai.html"><div class="state"><span class="dot ${(state.mode==='direct'?state.claude:state.platformConnected)?'success':'danger'}"></span>${state.mode==='codemie'?(state.platformConnected?'CodeMie profile':'CodeMie · needs setup'):(state.claude?'Claude Code · Direct':'Claude Code · needs setup')}</div><div class="dim">${state.mode==='codemie'?'Personal project':'Own account · no platform required'}</div></a><div class="profile"><span class="avatar">VV</span><div class="grow"><strong class="small">Vadym</strong><div class="dim" style="font-size:9px">Personal workspace</div></div><button class="icon-btn" data-action="profile" aria-label="Workspace menu">${icon('more')}</button></div></div></aside><main class="main" id="main"><div class="topbar"><button class="icon-btn mobile-menu" data-action="mobile-menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span>${icon('chevron')}<strong>${PAGE_INFO[page][0]}</strong></div><div class="global-spacer"></div><button class="global-capture" data-action="${state.recording?'go:capture':'capture-menu'}">${icon(state.recording?'mic':'video')}<span class="capture-label">${state.recording?'Recording · '+esc(state.recordTitle||'Workspace sync'):'10:00 · Product sync'}</span><b>${state.recording?'LIVE':'Capture'}</b></button><a class="global-budget" href="analytics.html">${state.mode==='codemie'?'$38.40 / $150':'Direct account'}<i></i></a><button class="search-trigger" data-action="palette" aria-label="Search workspace or jump to a page">${icon('search')}</button><button class="global-ask" data-action="context-ask">${icon('spark')}<span>Ask</span><kbd>⌘ J</kbd></button><button class="icon-btn" data-action="theme" aria-label="Toggle light and dark theme">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}</button></div><div class="content"><div class="content-inner" id="page"></div></div></main><footer class="footer"><button data-action="prototype-menu">${icon('sliders')}Prototype · sample data</button><span class="footer-status"><span class="dot success"></span> Synced 09:42</span><a class="footer-extra" href="knowledge.html">Personal knowledge · 214 pages</a><a class="footer-extra" href="settings-ai.html">${state.mode==='direct'?'Claude Code · direct':'CodeMie · project default'}</a><span class="push">${state.recording?'Recording in progress':'Monday, 16 Nov · Europe/Kyiv'}</span><a href="proposal.html">Proposal v2</a></footer></div><div id="modal-root"></div><div id="context-root"></div><div class="toast-container" aria-live="polite"></div>`;
 renderPage();
};
const setupNudge=()=>!state.setup&&!state.setupDismissed?`<div class="setup-banner"><span class="banner-icon">${icon('terminal')}</span><div class="grow"><h3>Finish setting up your AI tools</h3><p>${state.claude?'Claude Code is detected. Verify your profile or connect CodeMie when you need it.':'Your workspace is available. Choose direct Claude Code or an optional CodeMie connection.'}</p></div>${linkBtn('Continue setup','settings-setup.html','arrow','primary')}<button class="icon-btn dismiss-banner" data-action="dismiss-setup" aria-label="Dismiss setup banner">${icon('close')}</button></div>`:'';
const source=(label,href='knowledge-pages.html')=>`<a class="source" href="${href}">${label}</a>`;
const widget=(id,title,body,action='',ico='')=>`<section class="panel workspace-widget" data-dashboard-widget="${id}" data-width="${state.workspaceWidgets.find(w=>w.id===id)?.width||'standard'}" draggable="${!!transient.layoutEditing}"><div class="panel-head"><h2>${transient.layoutEditing?'<span class="drag-handle" aria-hidden="true">⠿</span>':icon(ico||workspaceWidgets.find(w=>w.id===id)?.ico||'grid')}${title}</h2>${action}</div>${body}</section>`;
function todayBrief(){return widget('brief','Morning brief',`<div class="widget-body"><ul class="brief-list"><li><span class="bullet">01</span><div><strong>${state.criticalAck?'Checkout incident acknowledged.':'Checkout incident needs your acknowledgement.'}</strong> Payments started failing at 08:18. Alex asked for an owner and an update time.${source('Outlook · 08:22','inbox.html')}</div></li><li><span class="bullet">02</span><div><strong>10:00 · Product sync.</strong> Settle the plugin host approach and what is available before connecting an account.${source('3 prep pages','meeting.html?meeting=1')}</div></li><li><span class="bullet">03</span><div><strong>Two decisions are still open.</strong> Keep the Echo package unchanged; reproduce its host contract. Choose the vault’s reviewed write policy.${source('Design review','meeting.html')}</div></li><li><span class="bullet">04</span><div><strong>You owe Jamie a prototype review today.</strong> Alex’s feedback on capture controls arrived this morning.${source('Commitments','index.html#work')}</div></li><li><span class="bullet">05</span><div><strong>Your knowledge changed overnight.</strong> Three pages added, twelve updated, one contradiction to resolve. Focus time is protected from 14:30.${source('Knowledge health','knowledge-health.html')}</div></li></ul><div class="widget-meta"><span>07:30 · 14 sources</span><span>Claude Code · direct</span><span>34 s · provider billing</span><button class="text-link" data-action="brief-provenance">Sources & run</button></div></div><div class="panel-foot"><button class="text-link" data-action="context-ask:brief">Ask a follow-up ${icon('arrow')}</button><button class="text-link" data-action="regenerate-brief">${icon('refresh')} Regenerate</button></div>`,linkBtn('Routine','automations.html','automation','ghost sm'))}
const decisionDefs=[['knowledge','book','Review 3 knowledge changes','Minutes propose updates to decisions, risks and your daily note.','knowledge-ingest.html','Review changes'],['minutes','video','Minutes are ready for review','Workspace design review · 3 decisions, 4 actions.','meeting.html','Open minutes'],['plugin','puzzle','GitHub update asks for access','Added event subscription. Your installed version keeps running.','plugin.html?id=github#permissions','Review access']];
function todayDecisions(){return widget('decisions','Waiting for you',decisionDefs.filter(x=>!state.reviewedDecisions.includes(x[0])).map(([id,ico,title,desc,href,label])=>`<div class="decision-row"><span class="decision-icon">${icon(ico)}</span><div class="grow"><h3>${title}</h3><p>${desc}</p><a class="text-link small" href="${href}">${label} ${icon('arrow')}</a></div><button class="icon-btn" data-action="dismiss-decision:${id}" aria-label="Dismiss ${title}">${icon('close')}</button></div>`).join('')||`<div class="widget-body"><p>All reviewed. New requests will appear here.</p></div>`,tag(decisionDefs.filter(x=>!state.reviewedDecisions.includes(x[0])).length,'blue'))}
function todayAgenda(){const rows=[['09:00','T','Workspace check-in','Teams · Workspace redesign · 30 min','3 open questions · 2 decisions','meeting.html'],['10:00','T','Product sync','Teams · Personal workspace · 30 min','Prep ready · Plugin host decision','meeting.html?meeting=1'],['11:30','G','Knowledge garden','Google Meet · Learning garden · 45 min','Review draft schema · 1 open question','meeting.html?meeting=3'],['13:00','Z','Architecture catch-up','Zoom · Workspace redesign · 30 min','API contract and native permissions','meeting.html?meeting=5']];return widget('agenda','Your day',`<div class="timeline">${rows.map(([time,platform,title,meta,desc,href],i)=>`${i===1?'<div class="now-line">NOW 09:42</div>':''}<div class="timeline-row ${i===1?'now':''}"><time>${time}</time><span class="timeline-dot"></span><div><h3><span class="timeline-platform">${platform}</span><a href="${href}">${title}</a></h3><p>${meta} · ${desc}</p><div class="timeline-links"><a href="${href}">Open prep</a><button data-action="arm-capture:${title}">${state.armedMeeting===title?'Armed · cancel':'Record when it starts'}</button></div></div></div>`).join('')}<div class="timeline-row"><time>14:30</time><span class="timeline-dot" style="background:var(--green)"></span><div class="focus-event"><h3>Focus · review the prototype</h3><p>90 min · Critical alerts only</p><a class="text-link small" href="settings-notifications.html">Manage interruptions</a></div></div></div><div class="panel-foot"><span>Microsoft 365 + Google Calendar · synced 09:42</span><a class="text-link" href="calendar.html">Full calendar ${icon('arrow')}</a></div>`,tag('4 meetings · 1 focus block'))}
function todayWork(){return widget('work','My commitments',`<div class="widget-body"><div class="view-tabs"><button class="${state.commitmentTab!=='owed'?'active':''}" data-action="commitment-tab:owe">I owe · 3</button><button class="${state.commitmentTab==='owed'?'active':''}" data-action="commitment-tab:owed">Owed to me · 2</button></div>${(state.commitmentTab==='owed'?[['feedback','Alex · capture feedback','Due today · design review 29:48'],['api','Jamie · host API inventory','Due tomorrow · Teams 09:12']]:[['review','Send Jamie the prototype review','Today · product sync 18:24'],['schema','Approve Knowledge write policy','Today · design review 32:10'],['plugin','Try the unchanged GitHub package','Tomorrow · compatibility notes']]).map(([id,title,desc])=>`<div class="metric-row" style="align-items:flex-start"><button class="check-task ${state.commitments[id]?'checked':''}" data-action="commitment:${id}" aria-label="Complete ${title}">${state.commitments[id]?icon('check'):''}</button><div class="grow ${state.commitments[id]?'done':''}"><b>${title}</b><p style="font-size:11px;margin-top:4px">${desc}</p></div></div>`).join('')}<div class="subtle-note">Extracted from sources. Review a commitment before adding it to your work.</div></div>`,linkBtn('All','space.html#work','','ghost sm'))}
function todayKnowledge(){return widget('knowledge','Knowledge',`<div class="widget-body"><div class="mini-stats"><div><b>+3</b><span>new pages</span></div><div><b>12</b><span>updated</span></div><div><b>1</b><span>conflict</span></div><div><b>214</b><span>pages</span></div></div><div class="metric-row mt"><a class="text-link" href="knowledge-health.html">Health 82 / 100</a><span>3 need you</span></div><a class="text-link small" href="knowledge-ingest.html">6 sources waiting for review ${icon('arrow')}</a><form class="inline-ask" id="today-ask-form"><input id="today-ask" placeholder="Ask your knowledge…" aria-label="Ask your knowledge"><button class="btn primary" type="submit">Ask</button></form><div class="subtle-note">Personal knowledge · read-only Ask</div></div>`,linkBtn('Open','knowledge.html','external','ghost sm'))}
function todayUsage(){return widget('usage',state.mode==='codemie'?'AI spend':'AI usage',`<div class="widget-body">${state.mode==='codemie'?'<div class="budget-amount">$38.40 <small>of $150 monthly cap</small></div><div class="bar"><i></i></div>':'<div class="budget-amount">27 <small>sessions this month</small></div><div class="readiness">'+icon('terminal')+'Direct Claude Code · your own account</div>'}<svg class="sparkline" viewBox="0 0 300 45" preserveAspectRatio="none" aria-label="AI activity increased over the last seven days"><polyline points="0,35 42,29 84,33 126,18 168,25 210,9 252,17 300,6"/></svg><div class="metric-row"><span>Briefs & routines</span><b>14 runs</b></div><div class="metric-row"><span>Chat / Ask</span><b>8 / 5 sessions</b></div><div class="subtle-note">${state.mode==='codemie'?'Platform budget + local per-job caps.':'Provider billing stays with your account. Estimated token usage is available per run.'}</div></div>`,linkBtn('Usage','analytics.html','arrow','ghost sm'))}
function todayFocus(){return widget('focus','Interruptions & focus',`<div class="widget-body"><div class="between"><strong class="small">${state.focusActive?'Focus is active':'Critical alerts only'}</strong>${toggle('criticalOnly','Critical alerts only',state.criticalOnly!==false)}</div><p style="margin-top:10px">During focus, let VIP messages and matching outage rules through. Everything else waits in Inbox.</p><div class="metric-row mt"><span>Rule order</span><b>Rules → AI evidence</b></div><div class="metric-row"><span>Escalation</span><b>Desktop → Telegram</b></div><div class="flex wrap mt">${btn(state.focusActive?'End focus':'Focus for 25 min',state.focusActive?'end-focus':'begin-focus','clock','sm')}${linkBtn('Rules','settings-notifications.html','sliders','ghost sm')}</div></div>`,tag('Personal'))}
function todayPluginWidget(id){const def=workspaceWidgets.find(w=>w.id===id);if(!pluginEnabled(def.plugin))return '';if(id==='github')return widget(id,def.name,`<div class="widget-body"><div class="metric-row"><a href="plugin.html?id=github">#482 · Plugin host contract</a>${tag('Review','blue')}</div><div class="metric-row"><span>#479 · Vault read grants</span>${tag('Checks pass','green')}</div><div class="subtle-note">Plugin contribution · 2 selected repositories</div></div>`,linkBtn('Settings','plugin.html?id=github#settings','','ghost sm'));if(id==='routines')return widget(id,def.name,`<div class="widget-body">${state.automations.slice(0,3).map(a=>`<div class="metric-row"><a href="automations.html">${esc(a.name)}</a><span>${a.enabled?'On':'Paused'}</span></div>`).join('')}</div>`);return widget(id,def.name,`<div class="widget-body"><p>Your package’s card rendered in a CodeMie host slot.</p>${btn('Start focus','begin-focus','clock','primary sm')}</div>`)}
pages.today=()=>`${head('Today','Monday, 16 November · 4 meetings · 3 requests waiting',btn(transient.layoutEditing?'Finish arranging':'Customize','customize-today','sliders')+btn('Quick capture','quick-capture','plus','primary'))}<div class="view-tabs"><a class="active" href="index.html">Overview</a><a href="calendar.html">Calendar</a><a href="inbox.html">Inbox</a><span class="grow"></span><a href="automations.html">Morning brief routine ${icon('chevron')}</a></div>${setupNudge()}${!state.criticalAck?`<div class="critical-strip"><span class="critical-mark">!</span><div class="grow"><strong>Critical · Checkout payments are failing</strong><p>Alex, 08:22: “We need an owner and an ETA.” Rule: client outage + VIP · confidence 98%</p></div>${btn('Review & acknowledge','critical-review','arrow','danger sm')}</div>`:''}<div class="workspace-grid ${transient.layoutEditing?'edit-layout':''}">${state.workspaceWidgets.map(w=>({brief:todayBrief,decisions:todayDecisions,agenda:todayAgenda,work:todayWork,knowledge:todayKnowledge,usage:todayUsage,focus:todayFocus}[w.id]?.()||todayPluginWidget(w.id))).join('')}</div><div class="prototype-disclaimer">Interactive sample workspace. Recording, AI, Microsoft Graph, installation and native plugin execution are simulated.</div>`;

customizeToday=function(){modal('Customize Today',`<p>Choose cards, set widths, and move them in reading order. You can also drag cards after choosing “Arrange on page”.</p><div id="v2-widget-picker">${v2WidgetPicker()}</div>`,btn('Restore defaults','reset-widgets','undo')+btn('Arrange on page','arrange-widgets','grid')+btn('Done','close-widget-picker','check','primary'),true)};
function v2WidgetPicker(){const ordered=[...state.workspaceWidgets.map(w=>w.id),...workspaceWidgets.map(w=>w.id).filter(id=>!state.workspaceWidgets.some(w=>w.id===id))];return ordered.map(id=>{const d=workspaceWidgets.find(w=>w.id===id),w=state.workspaceWidgets.find(w=>w.id===id),blocked=d.plugin&&!pluginEnabled(d.plugin);return `<div class="widget-picker-row"><label><input type="checkbox" data-v2-widget="${id}" ${w?'checked':''} ${blocked?'disabled':''}><span><strong>${d.name}</strong><span style="display:block;color:var(--text2);font-size:10px">${d.from}${blocked?' · enable plugin first':''}</span></span></label>${w?`<select data-widget-width="${id}" aria-label="Width of ${d.name}">${['standard','wide','full'].map(x=>`<option ${w.width===x?'selected':''}>${x}</option>`).join('')}</select><div class="widget-controls"><button class="icon-btn" data-action="v2-widget-move:${id}:-1" aria-label="Move ${d.name} earlier">${icon('back')}</button><button class="icon-btn" data-action="v2-widget-move:${id}:1" aria-label="Move ${d.name} later">${icon('arrow')}</button></div>`:d.plugin?linkBtn('Plugin','plugin.html?id='+d.plugin,'puzzle','ghost sm'):''}</div>`}).join('')}
knowledgeTabs=function(selected){const sel=selected==='knowledge'&&(page==='knowledge-pages'||new URLSearchParams(location.search).has('doc'))?'knowledge-pages':selected;return `<nav class="tabs" aria-label="Knowledge sections">${[['knowledge','Home'],['knowledge-pages','Pages'],['knowledge-graph','Graph'],['knowledge-ask','Ask'],['knowledge-ingest','Ingest · 6'],['knowledge-health','Health · 3'],['knowledge-setup','Schema & skills']].map(([id,label])=>`<a class="tab ${sel===id?'active':''}" href="${route(id)}">${label}</a>`).join('')}</nav>`};
function vaultHeader(actions=''){return `${head('Knowledge',`${esc(state.vaultName||'Personal knowledge')} · 214 pages · Obsidian vault · last change 09:31`,linkBtn('Vault settings','knowledge-setup.html','folder')+actions)}${knowledgeTabs(page)}`}
pages['knowledge-pages']=()=>baseKnowledgeReader().replace('Your notes. Your ideas. Useful everywhere.','Personal knowledge · Markdown files · reviewed writes');
pages.knowledge=()=>new URLSearchParams(location.search).has('doc')?baseKnowledgeReader():`${vaultHeader(btn('New page','new-document','plus','primary'))}<div class="detail-grid"><div class="stack">${panel('Your knowledge, in your files',`<div class="widget-body"><div class="flow-row" style="grid-template-columns:1fr 1fr 1fr"><a class="flow-step" href="knowledge-ingest.html"><div class="step-type">01 · SOURCES</div><strong>Raw, kept intact</strong><span>Meeting transcripts, mail, files<br>raw_inbox/ · 6 waiting</span></a><a class="flow-step" href="knowledge-pages.html"><div class="step-type">02 · PAGES</div><strong>Your connected wiki</strong><span>214 Markdown pages<br>Read, edit, undo</span></a><a class="flow-step" href="knowledge-setup.html"><div class="step-type">03 · RULES</div><strong>Schema & skills</strong><span>Templates, taxonomy, CLAUDE.md<br>7 vault skills · 12 personal skills</span></a></div><p class="mt">Connect an existing folder as it is. Keep your filenames, links, Obsidian setup and Git history.</p></div>`,'','book')}${panel('Ask your knowledge',`<div class="widget-body"><form class="inline-ask" id="today-ask-form"><input id="today-ask" placeholder="What should I know before the product sync?" aria-label="Ask your knowledge"><button class="btn primary" type="submit">Ask</button></form><div class="flex wrap mt">${['Prepare for my next meeting','Which decisions are still open?','What changed this week?'].map(t=>`<a class="chip" href="knowledge-ask.html?ask=${encodeURIComponent(t)}">${t}</a>`).join('')}</div><div class="setting-row" style="padding:16px 0 0"><div><h3>Also search raw sources · Recall</h3><p>Opt in to meeting, mail and file excerpts. Citations show the source.</p></div>${toggle('recall','Search raw sources',state.recall)}</div></div>`,tag('Claude Code · read-only'),'spark')}${panel('Recently changed',`<div class="list-row">${icon('file')}<div class="grow"><h3>Workspace redesign / decisions.md</h3><p>Meeting recipe · Design review · 09:31</p></div>${tag('+8 −1','green')}${btn('Diff','knowledge-history','code','ghost sm')}</div><div class="list-row">${icon('file')}<div class="grow"><h3>notes / 2026-11-16.md</h3><p>Morning brief · 07:30 · reviewed</p></div>${tag('+12','green')}<a class="text-link" href="knowledge-pages.html">Open</a></div><div class="list-row">${icon('file')}<div class="grow"><h3>CATALOG.md</h3><p>Deterministic index refresh · no model</p></div>${tag('Updated')}</div>`,linkBtn('All pages','knowledge-pages.html','arrow','ghost sm'),'clock')}</div><aside class="stack">${panel('Personal knowledge',`<div class="widget-body"><div class="metric-row"><span>Folder</span><b>~/AI/personal-knowledge</b></div><div class="metric-row"><span>Pages root</span><b>knowledge/</b></div><div class="metric-row"><span>Git</span><b>main · 071e3b</b></div><div class="metric-row"><span>AI profile</span><b>Direct Claude Code</b></div><div class="metric-row"><span>Write policy</span><b>${state.vaultReadonly?'Read only':'Review each diff'}</b></div><div class="flex wrap mt">${btn('Switch vault','switch-vault','folder','sm')}${linkBtn('Schema & access','knowledge-setup.html','','ghost sm')}</div></div>`,'','folder')}${panel('Needs your attention',`<a class="list-row" href="knowledge-health.html"><div class="grow"><h3>1 contradiction</h3><p>Launch date differs across two pages</p></div>${icon('chevron')}</a><a class="list-row" href="knowledge-ingest.html"><div class="grow"><h3>6 incoming sources</h3><p>3 have proposed changes</p></div>${icon('chevron')}</a><a class="list-row" href="knowledge-health.html"><div class="grow"><h3>Health · 82 / 100</h3><p>3 need you · 6 deterministic fixes</p></div>${icon('chevron')}</a>`,'','heart')}</aside></div>`;
pages['knowledge-setup']=()=>`${vaultHeader(btn('Add vault','connect-vault','plus','primary'))}<div class="panel"><div class="module-detail"><nav class="view-tabs">${['Vault','Schema','Skills','Sources','Access'].map(t=>`<button class="${state.vaultTab===t?'active':''}" data-action="vault-tab:${t}">${t}</button>`).join('')}</nav>${vaultSettingsBody()}</div></div>`;
function vaultSettingsBody(){switch(state.vaultTab){case 'Schema':return `<h2>Schema lives with your vault</h2><p class="subtle-note">Keep CLAUDE.md, templates and taxonomy in the folder. Drift is a proposed diff.</p><div class="panel">${settingRow('Page templates','meeting.md · decision.md · person.md · concept.md',btn('Inspect','schema-file:templates/decision.md','file','sm'))}${settingRow('Taxonomy','24 tags · 17 terms · no automatic vocabulary expansion',btn('Inspect','schema-file:TAG_TAXONOMY.md','file','sm'))}${settingRow('Vault instructions','Folder layout, source rules and editing policy',btn('Inspect','schema-file:CLAUDE.md','file','sm'))}</div><div class="notice mt">New tags and schema changes always join the review queue.</div>`;case 'Skills':return `<h2>Skills for the selected profile</h2><p class="subtle-note">Personal skills are discovered from the active profile. They stay in their own folders.</p><div class="panel">${settingRow('/personal-twin','~/.claude/skills/personal-twin · profile skill',btn('View instructions','schema-file:~/.claude/skills/personal-twin/SKILL.md','file','sm'))}${settingRow('/meeting-prep','~/.claude/skills/meeting-prep · profile skill',btn('Try in Ask','go:knowledge-ask','spark','sm'))}${settingRow('process-inbox · vault skill','.claude/skills/process-inbox · proposes reviewed changes',linkBtn('Open ingest','knowledge-ingest.html','arrow','sm'))}${settingRow('lint-wiki · vault skill','.claude/skills/lint-wiki · deterministic checks + proposals',linkBtn('Open health','knowledge-health.html','arrow','sm'))}</div>`;case 'Sources':return `<h2>Sources & ingestion</h2><div class="panel mt">${settingRow('Raw sources','raw_inbox/ is immutable. Approved results are separate pages.',tag('Append only','green'))}${settingRow('Meeting transcripts','Selected recordings only, after review',toggle('vaultMeetings','Use reviewed meeting sources',state.vaultMeetings!==false))}${settingRow('OneDrive','Files chosen through the Microsoft 365 connection',linkBtn('Choose files','files.html','folder','sm'))}${settingRow('Watch folder','Local sources arrive in the queue; no automatic write approval',btn('Choose folder','watch-folder','folder','sm'))}</div>`;case 'Access':return `<h2>Profile & folder access</h2><p class="subtle-note">Permissions apply to a profile and folder. A plugin does not inherit all workspace access.</p><div class="table-scroll"><table class="route-table"><tr><th>Profile</th><th>knowledge/</th><th>raw_inbox/</th><th>Personal skills</th></tr><tr><td>Direct Claude Code</td><td>Read · reviewed writes</td><td>${state.recall?'Read selected':'Off in Ask'}</td><td>Read only</td></tr><tr><td>CodeMie profile</td><td>${state.platformVaultGrant?'Read':'No access'}</td><td>No access</td><td>Own catalog</td></tr><tr><td>Plugins</td><td>Per-package grant</td><td>No access</td><td>No access</td></tr></table></div><div class="panel mt">${settingRow('CodeMie may read this vault','Separate consent; selecting a default AI profile does not grant access.',toggle('platformVaultGrant','Allow CodeMie to read vault',state.platformVaultGrant))}${settingRow('Read-only vault','Block page creation, ingestion approvals and repairs.',toggle('vaultReadonly','Read-only vault',state.vaultReadonly))}</div>`;default:return `<h2>Personal knowledge</h2><p class="subtle-note">Existing Obsidian vault · connected in place</p><div class="panel">${settingRow('Folder',esc(state.vaultFolder||'~/AI/personal-knowledge'),btn('Change','connect-vault','folder','sm'))}${settingRow('Pages in','knowledge/ · raw sources stay outside the wiki',tag('As found'))}${settingRow('Obsidian','Keep .obsidian, attachments and wiki links',btn('Open externally','open-obsidian','external','sm'))}${settingRow('Git commits','One commit per approved change set; source + skill in the message',toggle('vaultGit','Commit every approved change',state.vaultGit!==false))}${settingRow('Local index cache','Derived search and graph data · safe to rebuild',btn('Rebuild','rebuild-cache','refresh','sm'))}${settingRow('Write policy','Every AI change is proposed as a diff.',tag(state.vaultReadonly?'Read only':'Reviewed writes','green'))}</div>`}}
